+        root,
+        &["add", "--package", &format!("{package}:{bump}"), "--summary", "change"],
+    );
+    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
+    git(root, &["add", "."]);
+    git(root, &["commit", "-q", "-m", "changeset"]);
